'use client';

import {
  TagsInput as TagsInputPrimitive,
  useTagsInput,
  useTagsInputContext,
  useTagsInputItemContext,
} from '@ark-ui/react/tags-input';
import { clsx } from 'clsx';
import type { ComponentProps, ComponentRef } from 'react';
import { forwardRef } from 'react';
import { CloseIcon } from '@/lib/moduix/icons/ui';
import { CloseButton } from '../close-button';
import styles from './TagsInput.module.css';

const TagsInput = forwardRef<
  ComponentRef<typeof TagsInputPrimitive.Root>,
  ComponentProps<typeof TagsInputPrimitive.Root>
>(function TagsInput({ className, ...props }, ref) {
  return (
    <TagsInputPrimitive.Root
      ref={ref}
      className={clsx(styles.root, className)}
      {...props}
      data-slot="tags-input-root"
    />
  );
});

const TagsInputRootProvider = forwardRef<
  ComponentRef<typeof TagsInputPrimitive.RootProvider>,
  ComponentProps<typeof TagsInputPrimitive.RootProvider>
>(function TagsInputRootProvider({ className, ...props }, ref) {
  return (
    <TagsInputPrimitive.RootProvider
      ref={ref}
      className={clsx(styles.root, className)}
      {...props}
      data-slot="tags-input-root-provider"
    />
  );
});

const TagsInputLabel = forwardRef<
  ComponentRef<typeof TagsInputPrimitive.Label>,
  ComponentProps<typeof TagsInputPrimitive.Label>
>(function TagsInputLabel({ className, ...props }, ref) {
  return (
    <TagsInputPrimitive.Label
      ref={ref}
      className={clsx(styles.label, className)}
      {...props}
      data-slot="tags-input-label"
    />
  );
});

const TagsInputControl = forwardRef<
  ComponentRef<typeof TagsInputPrimitive.Control>,
  ComponentProps<typeof TagsInputPrimitive.Control>
>(function TagsInputControl({ className, ...props }, ref) {
  return (
    <TagsInputPrimitive.Control
      ref={ref}
      className={clsx(styles.control, className)}
      {...props}
      data-slot="tags-input-control"
    />
  );
});

const TagsInputItem = forwardRef<
  ComponentRef<typeof TagsInputPrimitive.Item>,
  ComponentProps<typeof TagsInputPrimitive.Item>
>(function TagsInputItem({ className, ...props }, ref) {
  return (
    <TagsInputPrimitive.Item
      ref={ref}
      className={clsx(styles.item, className)}
      {...props}
      data-slot="tags-input-item"
    />
  );
});

const TagsInputItemPreview = forwardRef<
  ComponentRef<typeof TagsInputPrimitive.ItemPreview>,
  ComponentProps<typeof TagsInputPrimitive.ItemPreview>
>(function TagsInputItemPreview({ className, ...props }, ref) {
  return (
    <TagsInputPrimitive.ItemPreview
      ref={ref}
      className={clsx(styles.itemPreview, className)}
      {...props}
      data-slot="tags-input-item-preview"
    />
  );
});

const TagsInputItemText = forwardRef<
  ComponentRef<typeof TagsInputPrimitive.ItemText>,
  ComponentProps<typeof TagsInputPrimitive.ItemText>
>(function TagsInputItemText({ className, ...props }, ref) {
  return (
    <TagsInputPrimitive.ItemText
      ref={ref}
      className={clsx(styles.itemText, className)}
      {...props}
      data-slot="tags-input-item-text"
    />
  );
});

const TagsInputItemDeleteTrigger = forwardRef<
  ComponentRef<typeof TagsInputPrimitive.ItemDeleteTrigger>,
  ComponentProps<typeof TagsInputPrimitive.ItemDeleteTrigger>
>(function TagsInputItemDeleteTrigger({ className, children, ...props }, ref) {
  return (
    <TagsInputPrimitive.ItemDeleteTrigger
      ref={ref}
      className={clsx(styles.itemDeleteTrigger, className)}
      {...props}
      data-slot="tags-input-item-delete-trigger"
    >
      {children ?? <CloseIcon />}
    </TagsInputPrimitive.ItemDeleteTrigger>
  );
});

const TagsInputItemInput = forwardRef<
  ComponentRef<typeof TagsInputPrimitive.ItemInput>,
  ComponentProps<typeof TagsInputPrimitive.ItemInput>
>(function TagsInputItemInput({ className, ...props }, ref) {
  return (
    <TagsInputPrimitive.ItemInput
      ref={ref}
      className={clsx(styles.itemInput, className)}
      {...props}
      data-slot="tags-input-item-input"
    />
  );
});

const TagsInputInput = forwardRef<
  ComponentRef<typeof TagsInputPrimitive.Input>,
  ComponentProps<typeof TagsInputPrimitive.Input>
>(function TagsInputInput({ className, ...props }, ref) {
  return (
    <TagsInputPrimitive.Input
      ref={ref}
      className={clsx(styles.input, className)}
      {...props}
      data-slot="tags-input-input"
    />
  );
});

const TagsInputClearTrigger = forwardRef<
  ComponentRef<typeof TagsInputPrimitive.ClearTrigger>,
  ComponentProps<typeof TagsInputPrimitive.ClearTrigger>
>(function TagsInputClearTrigger({ asChild, className, children, ...props }, ref) {
  // Ark merges its label, anatomy, and state props onto the CloseButton host.
  return (
    <TagsInputPrimitive.ClearTrigger
      ref={ref}
      asChild
      className={clsx(styles.clearTrigger, className)}
      {...props}
      data-slot="tags-input-clear-trigger"
    >
      {asChild ? children : <CloseButton>{children}</CloseButton>}
    </TagsInputPrimitive.ClearTrigger>
  );
});

const TagsInputHiddenInput = TagsInputPrimitive.HiddenInput;
const TagsInputContext = TagsInputPrimitive.Context;
const TagsInputItemContext = TagsInputPrimitive.ItemContext;

function TagsInputItems() {
  return (
    <TagsInputContext>
      {(tagsInput) =>
        tagsInput.value.map((value, index) => (
          <TagsInputItem key={`${value}-${index}`} index={index} value={value}>
            <TagsInputItemPreview>
              <TagsInputItemText>{value}</TagsInputItemText>
              <TagsInputItemDeleteTrigger />
            </TagsInputItemPreview>
            <TagsInputItemInput />
          </TagsInputItem>
        ))
      }
    </TagsInputContext>
  );
}

export {
  TagsInput,
  TagsInputClearTrigger,
  TagsInputContext,
  TagsInputControl,
  TagsInputHiddenInput,
  TagsInputInput,
  TagsInputItem,
  TagsInputItemContext,
  TagsInputItemDeleteTrigger,
  TagsInputItemInput,
  TagsInputItemPreview,
  TagsInputItemText,
  TagsInputItems,
  TagsInputLabel,
  TagsInputRootProvider,
  useTagsInput,
  useTagsInputContext,
  useTagsInputItemContext,
};

export type {
  TagsInputClearTriggerProps,
  TagsInputContextProps,
  TagsInputControlProps,
  TagsInputFocusOutsideEvent,
  TagsInputHighlightChangeDetails,
  TagsInputHiddenInputProps,
  TagsInputInputProps,
  TagsInputInputValueChangeDetails,
  TagsInputInteractOutsideEvent,
  TagsInputItemContextProps,
  TagsInputItemDeleteTriggerProps,
  TagsInputItemInputProps,
  TagsInputItemPreviewProps,
  TagsInputItemProps,
  TagsInputItemTextProps,
  TagsInputLabelProps,
  TagsInputPointerDownOutsideEvent,
  TagsInputRootProps,
  TagsInputRootProviderProps,
  TagsInputValidityChangeDetails,
  TagsInputValueChangeDetails,
  UseTagsInputContext,
  UseTagsInputItemContext,
  UseTagsInputProps,
  UseTagsInputReturn,
} from '@ark-ui/react/tags-input';

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    gap: var(--moduix-spacing-1);
    width: var(--moduix-tags-input-width, 24rem);
    max-width: 100%;
    color: var(--moduix-color-foreground);

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);

      :where(
          [data-slot='field-root'][data-disabled],
          [data-slot='field-root-provider'][data-disabled],
          [data-slot='fieldset-root'][data-disabled],
          [data-slot='fieldset-root-provider'][data-disabled]
        )
        & {
        opacity: 1;
      }
    }
  }

  .label {
    display: inline-flex;
    align-items: center;
    gap: var(--moduix-spacing-1);
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
  }

  .control {
    box-sizing: border-box;
    display: flex;
    min-height: var(--moduix-tags-input-min-height, var(--moduix-size-md));
    flex-wrap: wrap;
    align-items: center;
    gap: var(--moduix-spacing-1);
    width: 100%;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-tags-input-radius, var(--moduix-radius-md));
    /* 5px keeps a one-line control at 36px around 24px tags and the 1px border. */
    padding: 0.3125rem var(--moduix-spacing-2);
    background-color: var(--moduix-color-background);
    outline: var(--moduix-focus-ring-inset-width) solid transparent;
    outline-offset: var(--moduix-focus-ring-inset-offset);
    transition:
      border-color var(--moduix-transition-default),
      outline-color var(--moduix-transition-default);

    &[data-focus] {
      outline-color: var(--moduix-color-ring);
    }

    &[data-invalid] {
      border-color: var(--moduix-color-destructive);

      &[data-focus] {
        outline-color: var(--moduix-color-destructive);
      }
    }

    &[data-disabled] {
      pointer-events: none;
    }
  }

  .item {
    display: contents;
  }

  .itemPreview {
    box-sizing: border-box;
    display: inline-flex;
    min-width: 0;
    max-width: 100%;
    align-items: center;
    gap: var(--moduix-spacing-1);
    min-height: var(--moduix-size-xs);
    border: var(--moduix-border-width-sm) solid transparent;
    border-radius: var(--moduix-radius-full);
    padding: var(--moduix-spacing-0-5) var(--moduix-spacing-2);
    background-color: var(--moduix-color-secondary);
    color: var(--moduix-color-secondary-foreground);
    font-size: var(--moduix-text-xs);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-xs);
    transition: box-shadow var(--moduix-transition-default);

    &[data-highlighted] {
      box-shadow: 0 0 0 var(--moduix-border-width-sm) var(--moduix-color-ring);
    }
  }

  .itemText {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .input,
  .itemInput {
    box-sizing: border-box;
    flex: 1 1 7rem;
    min-width: 7rem;
    height: var(--moduix-size-xs);
    margin: 0;
    border: 0;
    padding: 0 var(--moduix-spacing-1);
    background-color: transparent;
    color: inherit;
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
    outline: 0;

    &::placeholder {
      color: var(--moduix-color-muted-foreground);
    }
  }

  .itemInput {
    flex-grow: 0;
  }

  .input[data-readonly],
  .control[data-readonly] .itemDeleteTrigger {
    display: none;
  }

  .itemDeleteTrigger {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    width: var(--moduix-spacing-4);
    height: var(--moduix-spacing-4);
    border: 0;
    border-radius: var(--moduix-radius-full);
    padding: 0;
    background-color: transparent;
    color: currentColor;
    cursor: pointer;
    outline: 0;
    transition:
      background-color var(--moduix-transition-default),
      box-shadow var(--moduix-transition-default);

    & > svg {
      width: var(--moduix-spacing-3);
      height: var(--moduix-spacing-3);
      flex: none;
      pointer-events: none;
    }

    @media (hover: hover) {
      &:hover {
        background-color: color-mix(in oklab, currentColor 12%, transparent);
      }
    }

    &:focus-visible {
      box-shadow: 0 0 0 var(--moduix-focus-ring-inset-width) var(--moduix-color-ring);
    }

    /* An item can be disabled on its own; a disabled root already dims the whole field. */
    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);
      pointer-events: none;

      .root[data-disabled] & {
        opacity: 1;
      }
    }
  }

  .clearTrigger {
    --moduix-close-button-size: var(--moduix-size-xs);
    --moduix-close-button-focus-ring-width: var(--moduix-border-width-sm);
    --moduix-close-button-focus-ring-offset: var(--moduix-border-width-sm);

    margin-inline-start: auto;

    &[data-readonly] {
      display: none;
    }

    .root[data-disabled] & {
      opacity: 1;
    }
  }
}
